42	/// The single customer a scenario's policies belong to, together with the
43	/// standing they have earned with MHPCO: how long they have been in business
44	/// with the office, and how many contracts it has already written for them.
45	/// Every policy-wide modifier is measured against this standing.
46	#[derive(Clone, Copy, Debug)]
47	pub struct Customer {
48	    pub years_with_mhpco: u32,
49	    pub contracts_written: u32,
50	}
51	
52	impl Customer {
53	    pub fn with_years(years_with_mhpco: u32) -> Self {
54	        Self {
55	            years_with_mhpco,
56	            contracts_written: 0,
57	        }
58	    }
59	
60	    /// MHPCO counts a contract as a follow-up once it has already written the
61	    /// customer at least one: every contract after their first, not merely the
62	    /// second.
63	    fn on_a_follow_up_contract(&self) -> bool {
64	        self.contracts_written > 0
65	    }
66	
67	    /// The office enters the contract it has just written into the customer's
68	    /// standing, so the next quote is measured against the fuller history.
69	    fn record_contract_written(&mut self) {
70	        self.contracts_written += 1;
71	    }
72	}
73	
74	/// Every component is insured for the same sum, whatever its type.
75	const COMPONENT_INSURANCE_VALUE: u64 = 250;
76	
77	/// Every component is insured at the same uniform rate, whatever its type.
78	const COMPONENT_BASE_PREMIUM: u64 = 25;
79	
80	/// What the MHPCO price list records against one item type: the name the
81	/// office trades under for it, and the base premium it charges. The office
82	/// keeps the two together because an item type exists on the list precisely
83	/// by being priced on it -- a type it can name but not price, or price but
84	/// not name, is not something it insures.
85	struct PriceListEntry {
86	    name: &'static str,
87	    insurance_value: u64,
88	    base_premium: u64,
89	}
90	
91	impl ItemType {
92	    /// This type's entry on the MHPCO price list. The one place the office
93	    /// enumerates what it insures: every item type it knows is named and
94	    /// priced here, and nowhere else.
95	    const fn price_list_entry(self) -> PriceListEntry {
96	        let (name, insurance_value, base_premium) = match self {
97	            Self::Sword => ("sword", 1000, 100),
98	            Self::Amulet => ("amulet", 600, 60),
99	            Self::Staff => ("staff", 800, 80),
100	            Self::Potion => ("potion", 400, 40),
101	            Self::Rune => ("rune", COMPONENT_INSURANCE_VALUE, COMPONENT_BASE_PREMIUM),
102	            Self::Moonstone => ("moonstone", COMPONENT_INSURANCE_VALUE, COMPONENT_BASE_PREMIUM),
103	        };
104	        PriceListEntry {
105	            name,
106	            insurance_value,
107	            base_premium,
108	        }
109	    }
110	
111	    /// Every item type the price list carries, in the order the list states
112	    /// them.
113	    const PRICE_LIST: [Self; 6] = [
114	        Self::Sword,
115	        Self::Amulet,
116	        Self::Staff,
117	        Self::Potion,
118	        Self::Rune,
119	        Self::Moonstone,
120	    ];
121	
122	    /// Resolves the item type MHPCO knows by this name on its price list.
123	    pub fn named(name: &str) -> Result<Self, String> {
124	        Self::PRICE_LIST
125	            .into_iter()
126	            .find(|item_type| item_type.price_list_entry().name == name)
127	            .ok_or_else(|| format!("MHPCO does not insure items of type {name}"))
128	    }
129	}
130	
131	fn base_premium(item_type: ItemType) -> u64 {
132	    item_type.price_list_entry().base_premium
133	}
134	
135	/// What MHPCO insures one item of this type for, as its price list records.
136	/// This is the unmodified figure: no premium modifier and no block discount
137	/// bears on what an item is insured for.
138	fn insurance_value(item_type: ItemType) -> u64 {
139	    item_type.price_list_entry().insurance_value
140	}
141	
142	/// A building block is formed by exactly this many alike components:
143	/// neither fewer nor more qualify for the special block premium.
144	const BLOCK_COMPONENT_COUNT: usize = 3;
145	
146	/// The special base premium MHPCO offers for one building block.
147	const BLOCK_BASE_PREMIUM: u64 = 60;
148	
149	fn alike_group_base_premium(item_type: ItemType, count: usize) -> u64 {
150	    if count == BLOCK_COMPONENT_COUNT {
151	        return BLOCK_BASE_PREMIUM;
152	    }
153	    count as u64 * base_premium(item_type)
154	}
155	
156	/// Gathers the policy's items into groups of alike items, counting each group.
157	/// MHPCO counts two items as alike when they are of exactly the same item type
158	/// -- a rune and a moonstone are not alike, so they form no building block
159	/// together, and no other attribute of an item bears on the grouping.
160	fn alike_groups(items: &[Item]) -> Vec<(ItemType, usize)> {
161	    let mut groups: Vec<(ItemType, usize)> = Vec::new();
162	    for item in items {
163	        match groups.iter_mut().find(|(alike, _)| *alike == item.item_type) {
164	            Some((_, count)) => *count += 1,
165	            None => groups.push((item.item_type, 1)),
166	        }
167	    }
168	    groups
169	}
170	
171	fn policy_base_premium(items: &[Item]) -> u64 {
172	    alike_groups(items)
173	        .into_iter()
174	        .map(|(item_type, count)| alike_group_base_premium(item_type, count))
175	        .sum()
176	}
177	
178	/// A cursed item carries this share of its base premium as a risk surcharge.
179	const CURSE_SURCHARGE_RATE: u64 = 50;
180	
181	/// Every MHPCO modifier is quoted as a rate out of this whole.
182	const PERCENT: u64 = 100;
183	
184	/// An amount of money as MHPCO carries it through a calculation: an exact
185	/// fraction of a G, counted in hundredths. The office keeps every intermediate
186	/// amount in this form and rounds only once, when the final premium or payout
187	/// leaves the calculation -- and it rounds in its own favor, so a premium goes
188	/// up to the next whole G.
189	#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Default)]
190	struct Hundredths(u64);
191	
192	impl Hundredths {
193	    const PER_G: u64 = 100;
194	
195	    const ZERO: Self = Self(0);
196	
197	    fn from_whole_g(whole_g: u64) -> Self {
198	        Self(whole_g * Self::PER_G)
199	    }
200	
201	    /// A rate of this amount, quoted as a percentage of it. MHPCO states
202	    /// every modifier this way, and the share stays exact in hundredths:
203	    /// a rate that does not divide the amount evenly is carried as a
204	    /// fraction rather than rounded here.
205	    fn percentage(self, rate: u64) -> Self {
206	        Self(self.0 * rate / PERCENT)
207	    }
208	
209	    /// Rounds up to whole G, as MHPCO does with a premium.
210	    fn rounded_up_to_whole_g(self) -> u64 {
211	        self.0.div_ceil(Self::PER_G)
212	    }
213	
214	    /// Rounds down to whole G, as MHPCO does with a payout.
215	    fn rounded_down_to_whole_g(self) -> u64 {
216	        self.0 / Self::PER_G
217	    }
218	
219	    fn saturating_sub(self, other: Self) -> Self {
220	        Self(self.0.saturating_sub(other.0))
221	    }
222	}
223	
224	impl std::ops::Add for Hundredths {
225	    type Output = Self;
226	
227	    fn add(self, other: Self) -> Self {
228	        Self(self.0 + other.0)
229	    }
230	}
231	
232	impl std::iter::Sum for Hundredths {
233	    fn sum<I: Iterator<Item = Self>>(amounts: I) -> Self {
234	        amounts.fold(Self::ZERO, |running, amount| running + amount)
235	    }
236	}
237	
238	/// A net change MHPCO applies to an amount. Surcharges raise it and discounts
239	/// lower it, and because the discounts can outweigh the surcharges the net may
240	/// fall either way -- so it is kept signed until it meets the amount it adjusts.
241	#[derive(Clone, Copy, Debug)]
242	struct Adjustment(i64);
243	
244	impl Adjustment {
245	    fn raising(surcharge: Hundredths) -> Self {
246	        Self(surcharge.0 as i64)
247	    }
248	
249	    fn lowered_by(self, discount: Hundredths) -> Self {
250	        Self(self.0 - discount.0 as i64)
251	    }
252	}
253	
254	impl std::ops::Add<Adjustment> for Hundredths {
255	    type Output = Self;
256	
257	    fn add(self, adjustment: Adjustment) -> Self {
258	        Self(self.0.saturating_add_signed(adjustment.0))
259	    }
260	}
261	
262	/// A risk surcharge is always levied as a percentage of the affected item's
263	/// own base premium -- never of the policy total.
264	fn risk_surcharge(item: &Item, rate: u64) -> Hundredths {
265	    Hundredths::from_whole_g(base_premium(item.item_type)).percentage(rate)
266	}
267	
268	fn curse_surcharge(item: &Item) -> Hundredths {
269	    if item.cursed {
270	        return risk_surcharge(item, CURSE_SURCHARGE_RATE);
271	    }
272	    Hundredths::ZERO
273	}
274	
275	/// From this enchantment level on, an item counts as highly enchanted.
276	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
277	
278	/// A highly enchanted item carries this share of its base premium as a
279	/// risk surcharge.
280	const HIGH_ENCHANTMENT_SURCHARGE_RATE: u64 = 30;
281	
282	fn high_enchantment_surcharge(item: &Item) -> Hundredths {
283	    if item.enchantment >= HIGH_ENCHANTMENT_LEVEL {
284	        return risk_surcharge(item, HIGH_ENCHANTMENT_SURCHARGE_RATE);
285	    }
286	    Hundredths::ZERO
287	}
288	
289	/// The hazards MHPCO levies on a single item. An item that is both cursed and
290	/// highly enchanted carries both surcharges; they stack rather than compete.
291	fn item_risk_surcharge(item: &Item) -> Hundredths {
292	    curse_surcharge(item) + high_enchantment_surcharge(item)
293	}
294	
295	fn item_risk_surcharges(items: &[Item]) -> Hundredths {
296	    items.iter().map(item_risk_surcharge).sum()
297	}
298	
299	/// From this many years of business on, a customer counts as long-standing.
300	const LOYALTY_YEARS: u32 = 2;
301	
302	/// A long-standing customer receives this share of the policy base premium
303	/// as a discount.
304	const LOYALTY_DISCOUNT_RATE: u64 = 20;
305	
306	fn loyalty_discount(customer: &Customer, policy_base_premium: Hundredths) -> Hundredths {
307	    if customer.years_with_mhpco >= LOYALTY_YEARS {
308	        return policy_base_premium.percentage(LOYALTY_DISCOUNT_RATE);
309	    }
310	    Hundredths::ZERO
311	}
312	
313	/// Every quote is a first insurance of the items it covers, so MHPCO levies
314	/// this share of the policy base premium as an initial assessment surcharge.
315	const INITIAL_ASSESSMENT_RATE: u64 = 10;
316	
317	fn initial_assessment_surcharge(policy_base_premium: Hundredths) -> Hundredths {
318	    policy_base_premium.percentage(INITIAL_ASSESSMENT_RATE)
319	}
320	
321	/// Each contract after the customer's first earns this share of the policy
322	/// base premium as a discount.
323	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE: u64 = 15;
324	
325	fn follow_up_contract_discount(customer: &Customer, policy_base_premium: Hundredths) -> Hundredths {
326	    if customer.on_a_follow_up_contract() {
327	        return policy_base_premium.percentage(FOLLOW_UP_CONTRACT_DISCOUNT_RATE);
328	    }
329	    Hundredths::ZERO
330	}
331	
332	/// The modifiers MHPCO levies on the policy as a whole rather than on any one
333	/// item: they are measured against the policy base premium rather than any
334	/// item's. The discounts may outweigh the surcharge, so the catalogue nets out
335	/// to a single adjustment that can fall either way.
336	fn policy_wide_modifiers(customer: &Customer, policy_base_premium: Hundredths) -> Adjustment {
337	    Adjustment::raising(initial_assessment_surcharge(policy_base_premium))
338	        .lowered_by(loyalty_discount(customer, policy_base_premium))
339	        .lowered_by(follow_up_contract_discount(customer, policy_base_premium))
340	}
341	
342	const PROCESSING_FEE: u64 = 5;
343	
344	/// MHPCO keeps this much of every damage event to itself.
345	const DEDUCTIBLE_G: u64 = 100;
346	
347	/// From this enchantment level on, MHPCO reimburses only half the damage.
348	const HALVED_REIMBURSEMENT_LEVEL: u32 = 8;
349	
350	/// The share of the damage MHPCO reimburses on a highly enchanted item.
351	const HALVED_REIMBURSEMENT_RATE: u64 = 50;
352	
353	/// A damage report matched to the insured item it refers to. MHPCO settles a
354	/// damage only against an item its policy actually covers, so the office
355	/// establishes the cover for every damage in the incident before it reimburses
356	/// any of them.
357	#[derive(Clone, Copy, Debug)]
358	struct CoveredDamage {
359	    item: Item,
360	    amount: u64,
361	}
362	
363	impl CoveredDamage {
364	    /// What MHPCO reimburses for this covered damage, before the policy cap.
365	    /// Two decisions in the order the policy wording puts them: the clause
366	    /// governing the damaged item first says what share of the damage is
367	    /// covered, and the deductible MHPCO keeps of every damage event is then
368	    /// taken off what that leaves.
369	    fn reimbursement(self) -> Hundredths {
370	        let covered = ReimbursementClause::governing(&self.item)
371	            .covers(Hundredths::from_whole_g(self.amount));
372	        covered.saturating_sub(Hundredths::from_whole_g(DEDUCTIBLE_G))
373	    }
374	}
375	
376	/// Reads the incident against the policy register, matching each damage report
377	/// to the insured item it refers to.
378	fn covered_damages(insured: &[Item], damages: &[Damage]) -> Vec<CoveredDamage> {
379	    damages
380	        .iter()
381	        .map(|damage| CoveredDamage {
382	            item: *insured
383	                .iter()
384	                .find(|item| item.item_type == damage.item_type)
385	                .expect("the damaged item is covered by the policy"),
386	            amount: damage.amount,
387	        })
388	        .collect()
389	}
390	
391	/// The clause of the MHPCO policy wording a damaged item falls under. Which
392	/// clause governs an item is a question about the item alone, settled before
393	/// any amount of money is named; what the clause then reimburses is stated
394	/// against the clause, not against the item.
395	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
396	enum ReimbursementClause {
397	    /// MHPCO reimburses only half the damage to a highly enchanted item.
398	    HighEnchantment,
399	    /// Absent any special clause, MHPCO reimburses the damage in full.
400	    Standard,
401	}
402	
403	impl ReimbursementClause {
404	    /// The clause this damaged item falls under.
405	    fn governing(item: &Item) -> Self {
406	        if item.enchantment >= HALVED_REIMBURSEMENT_LEVEL {
407	            return Self::HighEnchantment;
408	        }
409	        Self::Standard
410	    }
411	
412	    /// What this clause covers of a damage it governs, before the deductible
413	    /// MHPCO withholds of every damage event is taken off. Each clause is
414	    /// stated as the share of the damage it reimburses.
415	    fn covers(self, damage: Hundredths) -> Hundredths {
416	        let reimbursed_share = match self {
417	            Self::HighEnchantment => HALVED_REIMBURSEMENT_RATE,
418	            Self::Standard => PERCENT,
419	        };
420	        damage.percentage(reimbursed_share)
421	    }
422	}
423	
424	/// What a policy insures its items for, all told.
425	fn insurance_sum(insured: &[Item]) -> u64 {
426	    insured
427	        .iter()
428	        .map(|item| insurance_value(item.item_type))
429	        .sum()
430	}
431	
432	/// MHPCO pays out at most this multiple of a policy's insurance sum.
433	const PAYOUT_CAP_MULTIPLE: u64 = 2;
434	
435	/// What a policy may still pay out. MHPCO opens it at twice the insurance
436	/// sum and never settles a claim for more than it holds, cutting a larger
437	/// reimbursement back to what is left.
438	#[derive(Clone, Copy, Debug)]
439	struct PolicyCap(u64);
440	
441	impl PolicyCap {
442	    /// The cap MHPCO opens on a freshly written policy.
443	    fn opened_on(insured: &[Item]) -> Self {
444	        Self(insurance_sum(insured) * PAYOUT_CAP_MULTIPLE)
445	    }
446	
447	    /// Settles a desired reimbursement against the cap: the office pays what
448	    /// the cap allows, and reports the cap left standing afterwards.
449	    fn settle(self, desired_payout: u64) -> Settlement {
450	        let payout = desired_payout.min(self.0);
451	        Settlement {
452	            payout,
453	            remaining_cap: self.0 - payout,
454	        }
455	    }
456	}
457	
458	/// What MHPCO owes for a whole incident, before the policy cap bears on it:
459	/// every covered damage the incident reports, reimbursed under the clause its
460	/// item falls under and less the deductible MHPCO keeps of each, added up.
461	fn incident_reimbursement(covered: &[CoveredDamage]) -> u64 {
462	    let reimbursement: Hundredths = covered
463	        .iter()
464	        .map(|damage| damage.reimbursement())
465	        .sum();
466	    reimbursement.rounded_down_to_whole_g()
467	}
468	
469	pub fn quote(customer: &Customer, items: &[Item]) -> u64 {
470	    let policy_base_premium = Hundredths::from_whole_g(policy_base_premium(items));
471	    let premium = policy_base_premium
472	        + item_risk_surcharges(items)
473	        + policy_wide_modifiers(customer, policy_base_premium)
474	        + Hundredths::from_whole_g(PROCESSING_FEE);
475	    premium.rounded_up_to_whole_g()
476	}
477	
478	/// One damaged item and what the damage amounts to.
479	#[derive(Clone, Copy, Debug)]
480	pub struct Damage {
481	    pub item_type: ItemType,
482	    pub amount: u64,
483	}
484	
485	impl Damage {
486	    pub fn to(item_type: ItemType, amount: u64) -> Self {
487	        Self { item_type, amount }
488	    }
489	}
