498	/// Identifies a policy the office has written.
499	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
500	pub struct PolicyRef(usize);
501	
502	/// The MHPCO office serving one customer through a scenario. It keeps the
503	/// customer's standing current as it works, so each operation sees the
504	/// history the office has accumulated for them so far.
505	pub struct ClaimOffice {
506	    customer: Customer,
507	    policies: Vec<Vec<Item>>,
508	}
509	
510	impl ClaimOffice {
511	    pub fn serving(customer: Customer) -> Self {
512	        Self {
513	            customer,
514	            policies: Vec::new(),
515	        }
516	    }
517	
518	    /// Writes a policy over the given items and returns a reference to it a
519	    /// later claim can be made against. The premium the office quotes for the
520	    /// policy is computed as for any quote; this entry point reports the
521	    /// policy rather than the premium.
522	    pub fn quote_policy(&mut self, items: &[Item]) -> PolicyRef {
523	        self.quote(items);
524	        self.enter_policy_in_the_register(items)
525	    }
526	
527	    /// The office enters the policy it has just written into its register, so
528	    /// a later claim can be settled against the items it covers.
529	    fn enter_policy_in_the_register(&mut self, items: &[Item]) -> PolicyRef {
530	        self.policies.push(items.to_vec());
531	        PolicyRef(self.policies.len() - 1)
532	    }
533	
534	    pub fn claim(&mut self, policy: PolicyRef, damages: &[Damage]) -> Option<Settlement> {
535	        let insured = &self.policies[policy.0];
536	        let covered = covered_damages(insured, damages);
537	        Some(PolicyCap::opened_on(insured).settle(incident_reimbursement(&covered)))
538	    }
539	
540	    pub fn quote(&mut self, items: &[Item]) -> u64 {
541	        let premium = quote(&self.customer, items);
542	        self.customer.record_contract_written();
543	        premium
544	    }
545	}
